-- unnamed.zip workspace installer / generated from archive
local function log(...) print("[unnamed installer]", ...) end
log("START")
local mk = makefolder
local wr = writefile
local isdir = isfolder
local rd = readfile
if type(mk) ~= "function" or type(wr) ~= "function" then
    error("Missing makefolder/writefile filesystem functions", 0)
end
local map = {}
local abc = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
for i = 1, #abc do map[string.byte(abc, i)] = i - 1 end
local function b64decode(s)
    local result, n, acc, bits = {}, 0, 0, 0
    for i = 1, #s do
        local c = string.byte(s, i)
        if c == 61 then break end
        local v = map[c]
        if v then
            acc = acc * 64 + v
            bits = bits + 6
            if bits >= 8 then
                bits = bits - 8
                n = n + 1
                result[n] = string.char(math.floor(acc / (2 ^ bits)) % 256)
                acc = acc % (2 ^ bits)
            end
        end
    end
    return table.concat(result)
end
local folderCount, fileCount, failures = 0, 0, 0
do
  local path = "unnamed"
  local ok, err = pcall(function()
    if type(isdir) ~= "function" or not isdir(path) then mk(path) end
  end)
  if ok then folderCount = folderCount + 1 else failures = failures + 1; warn("[unnamed installer] FOLDER ERROR", path, err) end
end
